let metBot=false;function botTalk(){if(metBot){dialogue([{name:'QAIRUBOT',icon:'🤖',text:'Замок ждёт у выхода. И не волнуйся: я тоже не успел повторить Байеса.'}]);return}metBot=true;saveGame();setObjective('Открой дверь QAIRU','Подойди к двери со светящейся панелью и нажми E.');dialogue([{name:'QAIRUBOT',icon:'🤖',role:'Твой напарник',text:'Связь с SANA оборвалась. Последний сигнал ведёт к EXPO, но сначала надо открыть дверь.'},{name:'ТЫ',icon:'🧑🏻',role:'Первокурсник QAIRU',text:'У нас завтра файнал, а сегодня мы спасаем город. Удобный график.'},{name:'QAIRUBOT',icon:'🤖',text:'Замок запросил код. Я нашёл подсказки — попробуем решить вместе.'}])}
function openDoor(){if(!metBot){dialogue([{name:'QAIRUBOT',icon:'🤖',text:'Я здесь, в центре аудитории! Сначала подойди ко мне.'}]);return}code=[];addOverlay(`<button class="close" id="close">✕ Закрыть</button><div class="tag">МИНИ-ИГРА 01 / ЗАМОК QAIRU</div><h2>Открой дверь</h2><p>Система запрашивает код. Прочитай записку и нажимай цифры справа.</p><div class="code-layout"><div><div class="note"><strong>📄 Записка друга</strong><p>1. Цифры 1, 2 и 3 используются по одному разу.</p><p>2. Первая цифра чётная.</p><p>3. Вторая цифра больше третьей.</p></div><div id="feedback" class="feedback">Попытки не ограничены. У тебя получится.</div><button class="button alt" id="code-hint">ПОДСКАЗКА БОТА</button></div><div><div class="digits" id="digits"></div><div class="keypad"><button data-digit="1">1</button><button data-digit="2">2</button><button data-digit="3">3</button><button id="erase" class="minor">⌫ СТЕРЕТЬ</button><button id="reset-code" class="minor">СБРОС</button><button id="check" class="minor">ПРОВЕРИТЬ</button></div></div></div><div id="next-step"></div><details class="explain"><summary>Как работает ИИ в этой задаче?</summary>Это CSP: каждая позиция кода — переменная. Цифры не повторяются, первая чётная, вторая больше третьей. Подсказка перебирает варианты, отвергая нарушающие правила.</details>`);document.getElementById('close').onclick=closeOverlay;document.querySelectorAll('[data-digit]').forEach(b=>b.onclick=()=>{if(code.length<3){code.push(+b.dataset.digit);drawCode()}});document.getElementById('erase').onclick=()=>{code.pop();drawCode()};document.getElementById('reset-code').onclick=()=>{code=[];drawCode()};document.getElementById('code-hint').onclick=()=>{let x=solveCode(code);document.getElementById('feedback').textContent=x?`Бот: следующая цифра — ${x[code.length]??'код уже набран'}.`:'С этими цифрами решения нет. Сотри последнюю.'};document.getElementById('check').onclick=checkCode;drawCode()}
function validCode(c){return c.length===3&&new Set(c).size===3&&c.every(v=>[1,2,3].includes(v))&&c[0]%2===0&&c[1]>c[2]}
function solveCode(prefix=[]){function go(a){if(a.length===3)return validCode(a)?a:null;for(const d of [1,2,3]){if(a.includes(d))continue;let x=go([...a,d]);if(x)return x}return null}return go(prefix)}
function drawCode(){document.getElementById('digits').innerHTML=[0,1,2].map(i=>`<span>${code[i]??'·'}</span>`).join('')}
function checkCode(){let f=document.getElementById('feedback');if(code.length!==3){f.textContent='Набери три цифры.';return}if(!validCode(code)){f.textContent='Не подошло. Сверься с подсказками и попробуй ещё раз.';beep(180);return}f.className='feedback good';f.textContent='✓ Дверь открыта!';document.getElementById('next-step').innerHTML='<div class="card-actions"><button class="button" id="to-city">ВЫЙТИ В АСТАНУ ↗</button></div>';document.getElementById('to-city').onclick=()=>{closeOverlay();setStage(2);saveGame();dialogue([{name:'ДРУГ',icon:'🧑🏻',role:'Студенческий чат',text:'Я бы помог, но я уже в общаге и снял носки. Удачи!'},{name:'QAIRUBOT',icon:'🤖',text:'Найди навигатор. Некоторые дороги закрыты — нам нужен безопасный маршрут к EXPO.'}])};beep(700)}
const W=8,H=5,START=24,GOAL=15;function neighbors(i){let x=i%W,y=Math.floor(i/W);return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,b])=>a>=0&&a<W&&b>=0&&b<H).map(([a,b])=>b*W+a)}
function astar(walls){const block=new Set(walls),open=[START],g=Array(40).fill(Infinity),from={},seen=[];g[START]=0;const h=i=>Math.abs(i%W-GOAL%W)+Math.abs(Math.floor(i/W)-Math.floor(GOAL/W));while(open.length){open.sort((a,b)=>g[a]+h(a)-g[b]-h(b));let u=open.shift();if(seen.includes(u))continue;seen.push(u);if(u===GOAL){let p=[u];while(p[0]!==START)p.unshift(from[p[0]]);return{path:p,seen}}for(let v of neighbors(u)){if(block.has(v))continue;let n=g[u]+1;if(n<g[v]){g[v]=n;from[v]=u;open.push(v)}}}return{path:null,seen}}
function openMap(){routeWalls=[...defaultWalls];routePath=null;visited=[];addOverlay(`<button class="close" id="close">✕ Закрыть</button><div class="tag">МИНИ-ИГРА 02 / НАВИГАТОР</div><h2>Найди дорогу до EXPO</h2><p>Улицы закрыты. Нажимай на клетки, чтобы открыть или закрыть их, затем попроси QairuBot найти путь.</p><div class="grid-layout"><div><div id="grid" class="grid" aria-label="Карта улиц"></div><p class="caption">🏫 QAIRU &nbsp; 🌐 EXPO &nbsp; ✕ закрыто &nbsp; зелёный — путь</p></div><div><div class="note"><strong>🤖 QAIRUBOT</strong><p>Я сравню возможные пути и покажу маршрут.</p></div><div id="feedback" class="feedback">Измени карту или найди путь.</div><div class="card-actions"><button class="button" id="find">НАЙТИ МАРШРУТ</button></div><div id="next-step"></div></div></div><details class="explain"><summary>Как работает A*?</summary>A* оценивает клетки по f = g + h. g — длина пути от старта, h — расстояние по горизонтали и вертикали до цели. Закрытые клетки обходятся. Карта условная.</details>`,true);document.getElementById('close').onclick=closeOverlay;document.getElementById('find').onclick=findPath;drawGrid()}
function drawGrid(){let grid=document.getElementById('grid');grid.innerHTML=Array.from({length:40},(_,i)=>{let s=i===START,g=i===GOAL,wall=routeWalls.includes(i),path=routePath?.includes(i),seen=visited.includes(i);return `<button data-tile="${i}" class="tile ${s?'start':g?'goal':wall?'wall':path?'path':seen?'seen':''}" aria-label="${s?'QAIRU':g?'EXPO':wall?'Закрытая улица':'Открытая улица'} ${Math.floor(i/W)+1},${i%W+1}" ${s||g?'disabled':''}>${s?'🏫':g?'🌐':wall?'✕':path?'•':''}</button>`}).join('');grid.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{let i=+b.dataset.tile;routeWalls=routeWalls.includes(i)?routeWalls.filter(v=>v!==i):[...routeWalls,i];routePath=null;visited=[];navComplete=false;saveGame();document.getElementById('next-step').innerHTML='';document.getElementById('feedback').textContent='Карта изменилась. Построй маршрут ещё раз.';drawGrid()})}
function findPath(){let result=astar(routeWalls);routePath=result.path;visited=result.seen;drawGrid();let f=document.getElementById('feedback');if(!result.path){f.textContent='Путь закрыт. Открой несколько красных клеток.';beep(180);return}navComplete=true;saveGame();f.className='feedback good';f.textContent=`✓ Маршрут найден: ${result.path.length-1} шагов. Проверено клеток: ${result.seen.length}.`;document.getElementById('next-step').innerHTML='<div class="card-actions"><button class="button" id="back">ПРОДОЛЖИТЬ ↗</button></div>';document.getElementById('back').onclick=()=>{closeOverlay();setObjective('Доберись до EXPO','Пройди вперёд к светящемуся входу и нажми E.');message('Маршрут готов. Иди к входу EXPO.');};beep(700)}
function cityExit(){if(!navComplete){dialogue([{name:'QAIRUBOT',icon:'🤖',text:'Сначала проверь карту на навигаторе. Мы не хотим замёрзнуть в тупике.'}]);return}setStage(3);saveGame();dialogue([{name:'QAIRUBOT',icon:'🤖',role:'EXPO · серверная',text:'Мы нашли серверную SANA. Осмотри улики, а ещё проверь модель безопасности на терминале AI LAB.'},{name:'ТЫ',icon:'🧑🏻',text:'А потом попробуем разобраться, кто за всем этим стоит.'}])}
function collect(c){if(!clues.includes(c.id)){clues.push(c.id);saveGame();}setObjective(`Собрано улик: ${clues.length} / 3`,clues.length<3?'Осматривай светящиеся устройства.':'Проверь AI LAB и подойди к терминалу SANA в конце комнаты.');dialogue([{name:'УЛИКА НАЙДЕНА',role:c.title,icon:c.icon,text:c.text},{name:'QAIRUBOT',icon:'🤖',text:'Записал. Проверим, как эта улика меняет вероятности на терминале.'}]);beep(680)}
function probabilities(){let p=[1/3,1/3,1/3];for(const id of clues){let e=clueData.find(c=>c.id===id);p=p.map((v,i)=>v*e.p[i]);let sum=p.reduce((a,b)=>a+b);p=p.map(v=>v/sum)}return p}

// A small binary Naive Bayes classifier. Features: unusual hour, failed logins, new device.
// These synthetic examples are split before fitting: test rows never enter model training.
const TRAIN_ML=[
 {x:[0,0,0],y:0},{x:[0,0,0],y:0},{x:[0,0,0],y:0},{x:[0,0,1],y:0},
 {x:[0,1,0],y:0},{x:[1,0,0],y:0},{x:[0,0,1],y:0},{x:[1,0,0],y:0},
 {x:[1,1,1],y:1},{x:[1,1,1],y:1},{x:[1,1,0],y:1},{x:[1,1,0],y:1},
 {x:[1,0,1],y:1},{x:[0,1,1],y:1},{x:[1,1,1],y:1},{x:[1,0,1],y:1}
];
const TEST_ML=[
 {x:[0,0,0],y:0},{x:[0,0,1],y:0},{x:[1,0,0],y:0},{x:[0,1,0],y:0},
 {x:[1,1,0],y:0},{x:[1,1,1],y:1},{x:[1,1,0],y:1},{x:[1,0,1],y:1},
 {x:[0,1,1],y:1},{x:[0,0,1],y:1},{x:[1,0,0],y:1},{x:[1,1,1],y:1}
];
function fitSecurityModel(rows){const counts=[0,0],ones=[[0,0,0],[0,0,0]];for(const row of rows){counts[row.y]++;row.x.forEach((v,i)=>{ones[row.y][i]+=v})}return {counts,ones,total:rows.length}}
function securityRisk(model,features){let scores=[0,1].map(y=>{let score=(model.counts[y]+1)/(model.total+2);for(let i=0;i<features.length;i++){let probability=(model.ones[y][i]+1)/(model.counts[y]+2);score*=features[i]?probability:1-probability}return score});return scores[1]/(scores[0]+scores[1])}
function securityEvaluate(model,rows,threshold){let tp=0,tn=0,fp=0,fn=0;const items=rows.map(row=>{let risk=securityRisk(model,row.x),prediction=risk>=threshold?1:0;if(prediction&&row.y)tp++;else if(prediction&&!row.y)fp++;else if(!prediction&&row.y)fn++;else tn++;return {...row,risk,prediction}});const divide=(a,b)=>b?a/b:0;const accuracy=divide(tp+tn,rows.length),precision=divide(tp,tp+fp),recall=divide(tp,tp+fn),f1=divide(2*precision*recall,precision+recall);return {tp,tn,fp,fn,accuracy,precision,recall,f1,items}}
const securityModel=fitSecurityModel(TRAIN_ML);
function openML(){addOverlay(`<button class="close" id="close">✕ Закрыть</button><div class="tag">ДОПОЛНИТЕЛЬНАЯ МИССИЯ / AI LAB</div><h2>Проверь защиту SANA</h2><p>В серверную поступают сигналы. Модель учится на <b>16 учебных примерах</b> различать обычные и подозрительные входы. После обучения она проверяет ещё <b>12 отдельных примеров</b>, которых не видела раньше.</p><div class="note"><strong>🤖 QairuBot</strong><p>«Перед выставкой мне нужно понять, не пропускает ли защита опасные сигналы. Попробуй изменить порог тревоги и сравни ошибки».</p></div><div class="ml-threshold"><label for="ml-threshold"><b>Порог тревоги: <span id="ml-value">50%</span></b><br><small>Если оценка модели не ниже порога, сигнал считается подозрительным.</small></label><input id="ml-threshold" type="range" min="10" max="90" step="5" value="50" aria-label="Порог тревоги"></div><div id="ml-results" aria-live="polite"></div><details class="explain"><summary>Как объяснить алгоритм и метрики на защите?</summary><p>Модель — наивный Байес для двух классов. Её признаки: необычное время, ошибки входа и новое устройство. Она оценивает вероятность подозрительного события. Параметры считаются только по обучающим примерам, затем качество считается по отдельному тесту. Данные и вероятности учебные; признаки условно считаются независимыми.</p><p>Accuracy = (TP + TN) / все. Precision = TP / (TP + FP). Recall = TP / (TP + FN). F1 = 2 × Precision × Recall / (Precision + Recall). Если знаменатель равен нулю, соответствующую метрику здесь выводим как 0.</p></details>`,true);document.getElementById('close').onclick=closeOverlay;const slider=document.getElementById('ml-threshold');slider.oninput=renderML;renderML()}
function renderML(){let threshold=Number(document.getElementById('ml-threshold').value)/100;document.getElementById('ml-value').textContent=Math.round(threshold*100)+'%';const r=securityEvaluate(securityModel,TEST_ML,threshold),percent=x=>Math.round(x*100)+'%';document.getElementById('ml-results').innerHTML=`<div class="ml-metrics"><div><b>${percent(r.accuracy)}</b><span>Accuracy</span><small>Все правильные ответы</small></div><div><b>${percent(r.precision)}</b><span>Precision</span><small>Тревоги, которые были верны</small></div><div><b>${percent(r.recall)}</b><span>Recall</span><small>Найденные опасные сигналы</small></div><div><b>${percent(r.f1)}</b><span>F1 score</span><small>Баланс Precision и Recall</small></div></div><div class="ml-table-wrap"><table class="ml-table"><caption>Что произошло на тесте · 12 сигналов</caption><thead><tr><th></th><th>На самом деле опасный</th><th>На самом деле обычный</th></tr></thead><tbody><tr><th>Модель: тревога</th><td class="ml-good">TP ${r.tp}<small>опасность найдена</small></td><td class="ml-error">FP ${r.fp}<small>ложная тревога</small></td></tr><tr><th>Модель: спокойно</th><td class="ml-error">FN ${r.fn}<small>пропущена опасность</small></td><td class="ml-good">TN ${r.tn}<small>верно: обычный</small></td></tr></tbody></table></div><p class="caption">TP + FP + FN + TN = ${r.tp+r.fp+r.fn+r.tn}. Ложные тревоги: ${r.fp}; пропущенные опасные сигналы: ${r.fn}. Попробуй переместить ползунок и сравнить результаты.</p><details class="explain"><summary>Посмотреть результаты всех 12 сигналов</summary><div class="ml-samples">${r.items.map((item,i)=>`<div><span>Сигнал ${i+1}</span><span>Риск: ${percent(item.risk)}</span><span>Модель: ${item.prediction?'тревога':'спокойно'}</span><span>Факт: ${item.y?'опасный':'обычный'}</span></div>`).join('')}</div></details>`}

function openCase(){let p=probabilities();addOverlay(`<button class="close" id="close">✕ Закрыть</button><div class="tag">МИНИ-ИГРА 03 / РАССЛЕДОВАНИЕ</div><h2>Кто отключил SANA?</h2><p>Улик найдено: <b>${clues.length} / 3</b>. Вернись к устройствам, если хочешь собрать больше, или выбери подозреваемого.</p><div class="note">${clues.length?clues.map(id=>{let e=clueData.find(c=>c.id===id);return `<p><b>${e.icon} ${e.title}:</b> ${e.text}</p>`}).join(''):'<p>Пока нет улик. Найди их в серверной.</p>'}</div><p>Оценка по учебной модели:</p><div class="bars">${p.map((v,i)=>`<div class="bar"><b>${names[i]}</b><div><i style="width:${v*100}%"></i></div><span>${Math.round(v*100)}%</span></div>`).join('')}</div><p class="caption">Вероятности основаны на вымышленных данных; это не доказательство.</p><div class="suspects">${names.map((n,i)=>`<button class="button alt" data-accuse="${i}">${n} ↗</button>`).join('')}</div><details class="explain"><summary>Как работает Байес?</summary>Каждая улика умножает текущую вероятность версии на условную вероятность этой улики. Результаты нормируются до суммы 100%. Модель учебная и предполагает условную независимость улик.</details>`);document.getElementById('close').onclick=closeOverlay;document.querySelectorAll('[data-accuse]').forEach(b=>b.onclick=()=>ending(+b.dataset.accuse))}
function ending(i){try{localStorage.removeItem(SAVE_KEY)}catch(e){}let ok=i===0;addOverlay(`<div class="end"><div class="tag">${ok?'МИССИЯ ВЫПОЛНЕНА':'ДЕЛО НЕ ЗАКРЫТО'}</div><h2>${ok?'Астана снова на связи':'Кажется, мы поспешили'}</h2><p>${ok?(clues.length<2?'Ты угадал:':'Ты обнаружил, что')+' Айдар отключил проверку SANA, чтобы скрыть ошибку в проекте.':`Ты обвинил ${['Айдара','Дану','Тимура'][i]}, но ошибся: проверку SANA отключил Айдар, скрывая ошибку в проекте.`}</p><div class="note"><strong>🤖 QAIRUBOT</strong><p>«Хорошая работа. Кстати, файнал по-прежнему завтра».</p></div><p>Собрано улик: ${clues.length} / 3.</p><div class="card-actions" style="justify-content:center"><button class="button" id="again">СЫГРАТЬ СНОВА ↗</button></div></div>`);document.getElementById('again').onclick=startGame}

function showJournal(){if(!active||modal)return;let entries=clueData.filter(c=>clues.includes(c.id));addOverlay(`<button class="close" id="close">✕ Закрыть</button><div class="tag">ДНЕВНИК ИССЛЕДОВАНИЯ</div><h2>Глава 0${stage} / 03</h2><p><b>Текущая цель:</b> ${obj.textContent}</p><p>${sub.textContent}</p><div class="note"><strong>📁 СОБРАНО УЛИК: ${clues.length} / 3</strong>${entries.length?entries.map(c=>`<p><b>${c.icon} ${c.title}</b> — ${c.text}</p>`).join(''):'<p>Улики появятся здесь, когда ты найдёшь их в EXPO.</p>'}</div><p class="caption">Прогресс по главам и найденные улики сохраняются в этом браузере. Положение и открытые головоломки после перезагрузки сбрасываются.</p><details class="explain"><summary>Управление</summary>WASD — движение; ← → или мышь — поворот; E — действие; Shift — бег. Нажми на сцену для управления мышью, Esc — чтобы освободить курсор.</details>`);document.getElementById('close').onclick=closeOverlay}
function beep(f){if(!soundEnabled)return;try{audio=audio||new AudioContext();if(audio.state==='suspended')audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.frequency.value=f;g.gain.setValueAtTime(.04,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+.12);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.13)}catch(e){}}
function nearest(){let best=null,dist=Infinity;for(let t of targets){let d=Math.hypot(position.x-t.x,position.z-t.z);if(d<dist){dist=d;best=t}}return dist<2.1?best:null}
function interact(){if(modal||!active)return;let target=nearest();if(target){beep(530);target.action()}else message('Подойди ближе к светящемуся маркеру.');}
function collides(x,z){let limit=stage===2?11.1:stage===1?8.7:8.1;if(Math.abs(x)>(stage===2?10.7:9.3)||Math.abs(z)>limit)return true;return solids.some(s=>Math.abs(x-s.x)<s.hx+.3&&Math.abs(z-s.z)<s.hz+.3)}
function animate(){requestAnimationFrame(animate);let dt=Math.min(clock.getDelta(),.05),time=clock.elapsedTime;if(active&&!modal){if(keys.ArrowLeft)yaw+=1.8*dt;if(keys.ArrowRight)yaw-=1.8*dt;let f=(keys.KeyW?1:0)-(keys.KeyS?1:0),side=(keys.KeyD?1:0)-(keys.KeyA?1:0),length=Math.hypot(f,side)||1,spd=(keys.ShiftLeft?7:4)*dt;let x=(-Math.sin(yaw)*f+Math.cos(yaw)*side)/length*spd,z=(-Math.cos(yaw)*f-Math.sin(yaw)*side)/length*spd;if(!collides(position.x+x,position.z))position.x+=x;if(!collides(position.x,position.z+z))position.z+=z;camera.position.copy(position);camera.position.y+=f||side?Math.sin(time*9)*.025:0;camera.rotation.set(pitch,yaw,0,'YXZ');let t=nearest();hint.hidden=!t;if(t)hint.innerHTML=`<span>E</span> ${t.label}`;}else hint.hidden=true;anim.forEach(fn=>fn(time));if(renderer&&scene&&camera)renderer.render(scene,camera)}
function startGame(){metBot=false;closeOverlay();setStage(1);saveGame();dialogue([{name:'ДРУГ',icon:'🧑🏻',role:'QAIRU · перед файналом',text:'Бро, ты понял Байеса? Я уже третий раз смотрю объяснение.'},{name:'ТЫ',icon:'🧑🏻',role:'Первокурсник',text:'Почти. Осталось только понять, что такое вероятность.'},{name:'SANA',icon:'📡',role:'Системное сообщение',text:'Сбой городской сети. Если вы слышите меня — найдите источник сигнала в EXPO.'},{name:'QAIRUBOT',icon:'🤖',text:'Кажется, подготовка к файналу только что стала приключением. Найди меня в аудитории.'}])}
function intro(){modal=true;overlay.innerHTML=`<div class="layer"><section class="card intro"><div class="intro-text"><div class="tag">СЮЖЕТНАЯ ИГРА · QAIRU / АСТАНА</div><h1>Последний <em>сигнал</em> Астаны.</h1><p>Завтра файнал. Сегодня городская система ИИ отключилась. Исследуй мир от первого лица, найди улики и помоги QairuBot восстановить связь.</p><div class="card-actions"><button class="button" id="start">НАЧАТЬ ИГРУ ↗</button>${readSave()?'<button class="button alt" id="resume">ПРОДОЛЖИТЬ ↗</button>':''}<a class="button alt" href="adventure2d.html">ПРЕЖНЯЯ 2D-ВЕРСИЯ</a></div><p class="cover-note">WASD — идти · ← → или мышь — смотреть · E — взаимодействовать<br>Для мыши нажми на игровое поле. Esc освободит курсор.</p></div><div class="intro-art"></div></section></div>`;document.getElementById('start').onclick=startGame;let b=document.getElementById('resume');if(b)b.onclick=resumeGame}
window.addEventListener('keydown',e=>{if(['KeyW','KeyA','KeyS','KeyD','ArrowLeft','ArrowRight','KeyE','ShiftLeft'].includes(e.code))e.preventDefault();if(modal)return;keys[e.code]=true;if(e.code==='KeyE'&&!e.repeat)interact()});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>keys={});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer?.domElement&&!modal){yaw-=e.movementX*.0025;pitch=Math.max(-.75,Math.min(.75,pitch-e.movementY*.0025))}});view.addEventListener('click',()=>{if(!modal&&renderer&&!document.pointerLockElement)renderer.domElement.requestPointerLock?.()});document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[k]=true});b.addEventListener('pointerup',()=>keys[k]=false);b.addEventListener('pointercancel',()=>keys[k]=false)});document.getElementById('touch-use').onclick=interact;document.getElementById('journal').onclick=showJournal;document.getElementById('restart').onclick=()=>{if(confirm('Начать игру сначала?'))startGame()};document.getElementById('sound').onclick=e=>{soundEnabled=!soundEnabled;e.currentTarget.textContent=soundEnabled?'♪ ЗВУК ВКЛ.':'♪ ЗВУК ВЫКЛ.';beep(650)};
if(init3D()){setStage(1);active=false;mission.hidden=true;controls.hidden=true;crosshair.hidden=true;touch.hidden=true;intro();animate()}
